function add(a, b) {
  let sum = a + b;
}
let total = add(5, 10);
console.log('Total: ' + total);

function subtract(a, b) {
  return a - b;
}
let result = subtract(3, 10);
console.log('10 - 3 = ' + result);

function isPositive(num) {
  if (num >= 0) {
    return true;
  } else {
    return false;
  }
}
let result = isPositive(5);
console.log(result);

function repeatMessage(message, times) {
  for (let i = 0; i <= times; i++) {
    console.log(message);
  }
}
repeatMessage('Boo!', 3);

function countdown(n) {
  if (n >= 0) {
    console.log(n);
    countdown(n - 1);
  } else {
    console.log('Boo!');
  }
}
countdown(3);
